#include <LiquidCrystal.h>
#include <math.h>

// =====================================================
// 1. PIN CONFIGURATION
// =====================================================

LiquidCrystal lcd(12, 11, 5, 4, 3, 2);

const int LM35_PIN   = A0;
const int HEATER_PIN = 9;
const int FAN_PIN    = 10;

// =====================================================
// 2. TEMPERATURE SETTINGS
// =====================================================

const double SETPOINT = 25.0;

// Heater hysteresis
const double HEATER_ON_TEMP  = 24.0;
const double HEATER_OFF_TEMP = 25.0;

// Fan hysteresis
const double FAN_ON_TEMP  = 26.0;
const double FAN_OFF_TEMP = 25.0;

// =====================================================
// 3. MOTOR SETTINGS
// =====================================================

const int MIN_PWM = 120;
const int MAX_PWM = 255;

// =====================================================
// 4. PID PARAMETERS
// =====================================================

double Kp = 45.0;
double Ki = 0.15;
double Kd = 1.5;

double integral = 0.0;
double previousError = 0.0;

// =====================================================
// 5. THERMAL SIMULATION MODEL
// =====================================================

// Approximate parameters for Proteus simulation.
// They are not measured real-greenhouse parameters.

const double HEATING_RATE = 0.20;
const double COOLING_RATE = 0.25;
const double PASSIVE_LOSS = 0.015;

// =====================================================
// 6. TEMPERATURE VARIABLES
// =====================================================

double ambientTemperature = 25.0;
double simulatedTemperature = 25.0;

// =====================================================
// 7. CONTROLLER STATE
// =====================================================

int heaterPWM = 0;
int fanPWM = 0;

bool heaterEnabled = false;
bool fanEnabled = false;

unsigned long lastControlTime = 0;
unsigned long lastLCDTime = 0;

// =====================================================
// 8. READ LM35
// =====================================================

double readLM35() {

  int sensorValue = analogRead(LM35_PIN);

  double voltage = sensorValue * (5.0 / 1023.0);

  // LM35 output = 10 mV per degree Celsius
  return voltage * 100.0;
}

// =====================================================
// 9. MOTOR PWM CONTROL
// =====================================================

int calculateMotorPWM(double errorMagnitude) {

  // Increase motor power when temperature is far
  // from the setpoint.

  double requestedPWM = 45.0 * errorMagnitude;

  requestedPWM = constrain(
    requestedPWM,
    0.0,
    (double)MAX_PWM
  );

  int pwm = (int)requestedPWM;

  // Avoid operating the motor at extremely low PWM.
  // If the requested power is too low, use MIN_PWM.

  if (pwm > 0 && pwm < MIN_PWM) {
    pwm = MIN_PWM;
  }

  return pwm;
}

// =====================================================
// 10. PID + HYSTERESIS CONTROLLER
// =====================================================

void updateController(double dt) {

  double error = SETPOINT - simulatedTemperature;

  // ---------------------------------------------------
  // HEATER STATE CONTROL
  // ---------------------------------------------------

  // Turn heater ON only at or below 23 C.
  if (simulatedTemperature <= HEATER_ON_TEMP) {
    heaterEnabled = true;
  }

  // Turn heater OFF at or above 24.5 C.
  else if (simulatedTemperature >= HEATER_OFF_TEMP) {
    heaterEnabled = false;
  }

  // ---------------------------------------------------
  // FAN STATE CONTROL
  // ---------------------------------------------------

  // Turn fan ON only at or above 26 C.
  if (simulatedTemperature >= FAN_ON_TEMP) {
    fanEnabled = true;
  }

  // Turn fan OFF at or below 24.5 C.
  else if (simulatedTemperature <= FAN_OFF_TEMP) {
    fanEnabled = false;
  }

  // ---------------------------------------------------
  // INTERLOCK
  // Never run heater and fan simultaneously.
  // ---------------------------------------------------

  if (heaterEnabled) {
    fanEnabled = false;
  }

  if (fanEnabled) {
    heaterEnabled = false;
  }

  // ---------------------------------------------------
  // PID CALCULATION
  // ---------------------------------------------------

  integral += error * dt;

  integral = constrain(
    integral,
    -30.0,
    30.0
  );

  double derivative = 0.0;

  if (dt > 0.0) {
    derivative = (error - previousError) / dt;
  }

  double pidOutput =
      Kp * error +
      Ki * integral +
      Kd * derivative;

  previousError = error;

  // ---------------------------------------------------
  // HEATER OUTPUT
  // ---------------------------------------------------

  if (heaterEnabled) {

    heaterPWM = calculateMotorPWM(fabs(pidOutput));

    fanPWM = 0;

  }

  // ---------------------------------------------------
  // FAN OUTPUT
  // ---------------------------------------------------

  else if (fanEnabled) {

    fanPWM = calculateMotorPWM(fabs(pidOutput));

    heaterPWM = 0;

  }

  // ---------------------------------------------------
  // BOTH MOTORS OFF
  // ---------------------------------------------------

  else {

    heaterPWM = 0;
    fanPWM = 0;

    // Prevent integral accumulation while idle.
    integral = 0.0;
  }

  // Apply PWM
  analogWrite(HEATER_PIN, heaterPWM);
  analogWrite(FAN_PIN, fanPWM);
}

// =====================================================
// 11. SIMULATED GREENHOUSE TEMPERATURE
// =====================================================

void updateTemperatureModel(double dt) {

  double heatingEffect =
      HEATING_RATE * ((double)heaterPWM / 255.0);

  double coolingEffect =
      COOLING_RATE * ((double)fanPWM / 255.0);

  // Passive heat exchange with the environment.
  double passiveEffect =
      PASSIVE_LOSS *
      (simulatedTemperature - ambientTemperature);

  // Update simulated temperature.
  simulatedTemperature +=
      (
        heatingEffect
        - coolingEffect
        - passiveEffect
      ) * dt;

  simulatedTemperature = constrain(
    simulatedTemperature,
    -20.0,
    100.0
  );
}

// =====================================================
// 12. LCD DISPLAY
// =====================================================

void updateLCD() {

  // First row: current temperature
  lcd.setCursor(0, 0);

  lcd.print("Temp:");
  lcd.print(simulatedTemperature, 1);
  lcd.write((byte)223);
  lcd.print("C    ");

  // Second row: actuator status
  lcd.setCursor(0, 1);

  if (heaterPWM > 0) {

    lcd.print("HEATER PWM:");
    lcd.print(heaterPWM);
    lcd.print("   ");

  }

  else if (fanPWM > 0) {

    lcd.print("FAN PWM:");
    lcd.print(fanPWM);
    lcd.print("      ");

  }

  else {

    lcd.print("TEMP STABLE     ");

  }
}

// =====================================================
// 13. SETUP
// =====================================================

void setup() {

  pinMode(HEATER_PIN, OUTPUT);
  pinMode(FAN_PIN, OUTPUT);

  // Start with both motors OFF.
  analogWrite(HEATER_PIN, 0);
  analogWrite(FAN_PIN, 0);

  lcd.begin(16, 2);

  lcd.setCursor(0, 0);
  lcd.print("SMART GREENHOUSE");

  lcd.setCursor(0, 1);
  lcd.print("PID CONTROLLER");

  delay(2000);

  // Read initial temperature from LM35.
  ambientTemperature = readLM35();

  // Initialize the thermal simulation.
  simulatedTemperature = ambientTemperature;

  previousError = SETPOINT - simulatedTemperature;

  lastControlTime = millis();
  lastLCDTime = millis();

  lcd.clear();
}

// =====================================================
// 14. MAIN LOOP
// =====================================================

void loop() {

  unsigned long now = millis();

  // Update the controller every 100 milliseconds.
  if (now - lastControlTime >= 100) {

    double dt =
        (now - lastControlTime) / 1000.0;

    lastControlTime = now;

    // Update the simulated greenhouse temperature.
    updateTemperatureModel(dt);

    // Update the PID and hysteresis controller.
    updateController(dt);
  }

  // Refresh LCD every 300 milliseconds.
  if (now - lastLCDTime >= 300) {

    lastLCDTime = now;

    updateLCD();
  }
}
